import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { before, describe, it } from 'node:test';

async function loadStyleDictionary() {
  try {
    // Tests run with cwd at the workspace root, which is the style-dictionary package root.
    const entry = pathToFileURL(join(process.cwd(), 'lib', 'StyleDictionary.js'));
    return (await import(entry.href)).default;
  } catch {
    // Fallback: package self-reference, valid when this file lives inside the package.
    return (await import('style-dictionary')).default;
  }
}

const StyleDictionary = await loadStyleDictionary();

/**
 * Multi-reference composite tokens: a two-layer shadow whose layers reference
 * dimension and color tokens (several of which resolve to the identical `0`),
 * plus a border whose width and color are references. All literal values are
 * fixed points of the css transform group so the expected output is exact.
 */
const tokens = {
  appearance: {
    shadow: {
      default: {
        layer: {
          1: {
            x: { value: '0', type: 'dimension' },
            y: { value: '0.5rem', type: 'dimension' },
            blur: { value: '1rem', type: 'dimension' },
            spread: { value: '-0.5rem', type: 'dimension' },
          },
          2: {
            x: { value: '0', type: 'dimension' },
            y: { value: '0', type: 'dimension' },
            blur: { value: '0', type: 'dimension' },
            spread: { value: '-1rem', type: 'dimension' },
          },
        },
      },
    },
    color: {
      shadow: {
        'layer-1': { value: 'rgba(71, 98, 133, 0.2)', type: 'color' },
        'layer-2': { value: 'rgba(11, 16, 24, 0.08)', type: 'color' },
      },
    },
  },
  size: {
    border: { width: { value: '0.125rem', type: 'dimension' } },
  },
  borderColor: { value: '#476285', type: 'color' },
  shadow: {
    default: {
      value: [
        {
          offsetX: '{appearance.shadow.default.layer.1.x}',
          offsetY: '{appearance.shadow.default.layer.1.y}',
          blur: '{appearance.shadow.default.layer.1.blur}',
          spread: '{appearance.shadow.default.layer.1.spread}',
          color: '{appearance.color.shadow.layer-1}',
        },
        {
          offsetX: '{appearance.shadow.default.layer.2.x}',
          offsetY: '{appearance.shadow.default.layer.2.y}',
          blur: '{appearance.shadow.default.layer.2.blur}',
          spread: '{appearance.shadow.default.layer.2.spread}',
          color: '{appearance.color.shadow.layer-2}',
        },
      ],
      type: 'shadow',
    },
  },
  border: {
    primary: {
      value: {
        width: '{size.border.width}',
        style: 'solid',
        color: '{borderColor}',
      },
      type: 'border',
    },
  },
};

async function buildCssFiles(fileOptions) {
  const outputDir = mkdtempSync(join(tmpdir(), 'sd-output-reference-fallbacks-'));
  const dictionary = new StyleDictionary({
    log: { verbosity: 'silent' },
    tokens: structuredClone(tokens),
    platforms: {
      css: {
        transformGroup: 'css',
        buildPath: `${outputDir}/`,
        files: fileOptions.map((options, index) => ({
          destination: `out-${index}.css`,
          format: 'css/variables',
          options: { showFileHeader: false, ...options },
        })),
      },
    },
  });
  await dictionary.buildAllPlatforms();
  const outputs = fileOptions.map((_, index) =>
    readFileSync(join(outputDir, `out-${index}.css`), 'utf8'),
  );
  rmSync(outputDir, { recursive: true, force: true });
  return outputs;
}

/** Extract the value of a `  --name: value;` custom property declaration. */
function declaration(css, name) {
  const match = css.match(new RegExp(`^ {2}--${name}: (.*);$`, 'm'));
  assert.ok(match, `expected a "  --${name}:" custom property declaration in output:\n${css}`);
  return match[1];
}

/** Inner text of every var(...) occurrence; fails loudly on unbalanced parens. */
function varInners(value) {
  const inners = [];
  for (let i = value.indexOf('var('); i !== -1; i = value.indexOf('var(', i + 1)) {
    let depth = 0;
    let close = -1;
    for (let k = i + 3; k < value.length; k++) {
      const ch = value[k];
      if (ch === '(') {
        depth++;
      } else if (ch === ')') {
        depth--;
        if (depth === 0) {
          close = k;
          break;
        }
      }
    }
    assert.notEqual(close, -1, `unbalanced parentheses in var(): ${value}`);
    inners.push(value.slice(i + 4, close));
  }
  return inners;
}

const EXPECTED_SHADOW_WITH_FALLBACKS =
  'var(--appearance-shadow-default-layer-1-x, 0) ' +
  'var(--appearance-shadow-default-layer-1-y, 0.5rem) ' +
  'var(--appearance-shadow-default-layer-1-blur, 1rem) ' +
  'var(--appearance-shadow-default-layer-1-spread, -0.5rem) ' +
  'var(--appearance-color-shadow-layer-1, rgba(71, 98, 133, 0.2)), ' +
  'var(--appearance-shadow-default-layer-2-x, 0) ' +
  'var(--appearance-shadow-default-layer-2-y, 0) ' +
  'var(--appearance-shadow-default-layer-2-blur, 0) ' +
  'var(--appearance-shadow-default-layer-2-spread, -1rem) ' +
  'var(--appearance-color-shadow-layer-2, rgba(11, 16, 24, 0.08))';

const EXPECTED_BORDER_WITH_FALLBACKS =
  'var(--size-border-width, 0.125rem) solid var(--border-color, #476285)';

const REFERENCE_ORDER = [
  'appearance-shadow-default-layer-1-x',
  'appearance-shadow-default-layer-1-y',
  'appearance-shadow-default-layer-1-blur',
  'appearance-shadow-default-layer-1-spread',
  'appearance-color-shadow-layer-1',
  'appearance-shadow-default-layer-2-x',
  'appearance-shadow-default-layer-2-y',
  'appearance-shadow-default-layer-2-blur',
  'appearance-shadow-default-layer-2-spread',
  'appearance-color-shadow-layer-2',
];

describe('object/array-valued tokens with outputReferences: true and outputReferenceFallbacks: true', () => {
  let css;

  before(async () => {
    [css] = await buildCssFiles([
      { outputReferences: true, outputReferenceFallbacks: true },
    ]);
  });

  it('emits one var(--ref, value) per reference and every fallback holds that reference\'s own resolved value', () => {
    assert.equal(declaration(css, 'shadow-default'), EXPECTED_SHADOW_WITH_FALLBACKS);
  });

  it('gives composite object-valued tokens like border their own per-reference fallbacks too', () => {
    assert.equal(declaration(css, 'border-primary'), EXPECTED_BORDER_WITH_FALLBACKS);
  });

  it('never nests one var() inside another var() fallback', () => {
    for (const name of ['shadow-default', 'border-primary']) {
      const value = declaration(css, name);
      for (const inner of varInners(value)) {
        assert.ok(
          !inner.includes('var('),
          `fallback of --${name} contains a nested var(): var(${inner})`,
        );
      }
    }
  });

  it('emits every reference exactly once in its own slot, even when several references resolve to the same value', () => {
    const value = declaration(css, 'shadow-default');

    assert.equal(
      (value.match(/var\(/g) ?? []).length,
      REFERENCE_ORDER.length,
      `expected exactly ${REFERENCE_ORDER.length} var() references in: ${value}`,
    );

    for (const ref of REFERENCE_ORDER) {
      const count = (value.match(new RegExp(`var\\(--${ref},`, 'g')) ?? []).length;
      assert.equal(count, 1, `expected exactly one var(--${ref}, ...) in: ${value}`);
    }

    // References that all resolve to the same value must each keep their own
    // fallback and their own slot — none dropped, collapsed, or moved.
    for (const fragment of [
      'var(--appearance-shadow-default-layer-1-x, 0)',
      'var(--appearance-shadow-default-layer-2-x, 0)',
      'var(--appearance-shadow-default-layer-2-y, 0)',
      'var(--appearance-shadow-default-layer-2-blur, 0)',
      'var(--appearance-shadow-default-layer-1-y, 0.5rem)',
      'var(--appearance-shadow-default-layer-1-blur, 1rem)',
      'var(--appearance-shadow-default-layer-1-spread, -0.5rem)',
      'var(--appearance-shadow-default-layer-2-spread, -1rem)',
      'var(--appearance-color-shadow-layer-1, rgba(71, 98, 133, 0.2))',
      'var(--appearance-color-shadow-layer-2, rgba(11, 16, 24, 0.08))',
    ]) {
      assert.ok(value.includes(fragment), `missing ${fragment} in: ${value}`);
    }

    let previous = -1;
    for (const ref of REFERENCE_ORDER) {
      const index = value.indexOf(`var(--${ref},`);
      assert.ok(
        index > previous,
        `var(--${ref}, ...) does not appear in its reference's own position in: ${value}`,
      );
      previous = index;
    }
  });
});

